float hash31(vec3 p){p=fract(p*0.1031);p+=dot(p,p.yzx+33.33);return fract((p.x+p.y)*p.z);}
vec3 hash33(vec3 p){p=fract(p*vec3(0.1031,0.1030,0.0973));p+=dot(p,p.yxz+33.33);return fract((p.xxy+p.yxx)*p.zyx);}
float hash21(vec2 p){vec3 p3=fract(vec3(p.xyx)*0.1031);p3+=dot(p3,p3.yzx+33.33);return fract((p3.x+p3.y)*p3.z);}
float noise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);
 float a=hash21(i),b=hash21(i+vec2(1,0)),c=hash21(i+vec2(0,1)),d=hash21(i+vec2(1,1));
 return mix(mix(a,b,f.x),mix(c,d,f.x),f.y);}
float fbm(vec2 p){float s=0.0,a=0.5;for(int i=0;i<4;i++){s+=a*noise(p);p=p*2.03+vec2(1.7,9.2);a*=0.5;}return s;}

vec3 stars(vec3 d){
 vec3 col=vec3(0);
 for(int l=0;l<3;l++){
  float s=70.0+float(l)*80.0;
  vec3 p=d*s;vec3 id=floor(p);vec3 f=fract(p)-0.5;
  vec3 h=hash33(id+float(l)*17.0);
  if(h.x>0.86){
   vec3 o=(hash33(id*1.7+3.0)-0.5)*0.5;
   float dist=length(f-o);
   float b=smoothstep(0.16,0.0,dist)*(0.4+0.6*h.y);
   b*=0.8+0.2*sin(iTime*3.0+h.z*40.0);
   vec3 tint=mix(vec3(1.0,0.75,0.55),vec3(0.65,0.8,1.0),h.z);
   col+=tint*b*b*2.0;
  }
 }
 float band=exp(-pow(dot(d,normalize(vec3(0.3,1.0,0.2)))*4.0,2.0));
 col+=vec3(0.05,0.045,0.07)*band*(0.5+fbm(d.xz*6.0+d.y*3.0));
 return col;
}

vec3 ramp(float x){
 vec3 c=mix(vec3(0.9,0.18,0.02),vec3(1.0,0.65,0.3),smoothstep(0.15,0.6,x));
 c=mix(c,vec3(1.0,0.95,0.85),smoothstep(0.6,1.1,x));
 c=mix(c,vec3(0.75,0.85,1.0),smoothstep(1.2,2.0,x));
 return c;
}

vec4 disk(vec3 p,vec3 dir){
 float r=length(p.xz);
 if(r<2.5||r>11.0)return vec4(0);
 float fade=smoothstep(2.5,3.1,r)*smoothstep(11.0,6.5,r);
 float om=3.0/pow(r,1.5);
 float th=om*iTime;float c=cos(th),s=sin(th);
 vec2 q=vec2(p.x*c+p.z*s,-p.x*s+p.z*c);
 float n1=fbm(q*1.4);
 float n2=noise(vec2(r*7.0,0.5));
 float dens=fade*(0.25+1.1*n1*n1*1.6)*(0.55+0.45*n2);
 float T=pow(3.0/r,1.1);
 vec3 vdir=normalize(vec3(-p.z,0.0,p.x));
 float beta=clamp(sqrt(0.5/r),0.0,0.7);
 float cs=dot(vdir,-normalize(dir));
 float g=sqrt(1.0-beta*beta)/(1.0-beta*cs);
 float boost=min(g*g*g,6.0);
 vec3 col=ramp(T*g)*dens*T*boost*2.2;
 float a=clamp(dens*1.1,0.0,1.0);
 return vec4(col,a);
}

void mainImage(out vec4 fragColor,in vec2 fragCoord){
 vec2 uv=(fragCoord-0.5*iResolution.xy)/iResolution.y;
 float t=iTime;
 float ang=t*0.09+0.6;
 float elev=0.13+0.07*sin(t*0.25);
 vec3 ro=17.0*vec3(cos(elev)*sin(ang),sin(elev),cos(elev)*cos(ang));
 vec3 fw=normalize(-ro);
 vec3 ri=normalize(cross(fw,vec3(0,1,0)));
 vec3 up=cross(ri,fw);
 vec3 rd=normalize(fw*1.5+uv.x*ri+uv.y*up);

 vec3 pos=ro;vec3 vel=rd;
 vec3 hv=cross(pos,vel);float h2=dot(hv,hv);
 vec3 col=vec3(0);float alpha=0.0;
 bool captured=false;
 for(int i=0;i<220;i++){
  float r=length(pos);
  if(r<1.0){captured=true;break;}
  if(r>40.0&&dot(pos,vel)>0.0)break;
  if(alpha>0.99)break;
  float dt=clamp(0.07*r,0.02,0.9);
  vec3 acc=-1.5*h2*pos/pow(r,5.0);
  vec3 pv=pos;
  vel+=acc*dt;
  pos+=vel*dt;
  if(pv.y*pos.y<0.0){
   float k=pv.y/(pv.y-pos.y);
   vec3 hit=mix(pv,pos,k);
   vec4 dsk=disk(hit,vel);
   col+=(1.0-alpha)*dsk.rgb*dsk.a;
   alpha+=(1.0-alpha)*dsk.a;
  }
 }
 if(!captured){
  col+=(1.0-alpha)*stars(normalize(vel));
 }
 col=1.0-exp(-col*1.3);
 col=pow(col,vec3(0.85));
 float vig=1.0-0.25*dot(uv,uv);
 fragColor=vec4(col*vig,1.0);
}
